//go:build !windows

package session

import (
	"context"
	"errors"
	"io"
	"os"
	"os/exec"
	"syscall"
	"time"

	"github.com/creack/pty"
)

// Start launches command under a direct PTY with argv, workdir, env, and size.
// Cancellation is controlled by ctx and WithTimeout.
func Start(ctx context.Context, command string, args []string, workdir string, env []string, size Size, opts ...Option) (*Session, error) {
	if command == "" {
		return nil, errors.New("command is required")
	}
	if err := validateSize(size); err != nil {
		return nil, err
	}
	cfg := applyOptions(opts)
	if ctx == nil {
		ctx = context.Background()
	}
	var timeoutCancel context.CancelFunc
	if cfg.Timeout > 0 {
		ctx, timeoutCancel = context.WithTimeout(ctx, cfg.Timeout)
	}
	runCtx, runCancel := context.WithCancel(ctx)
	cancel := func() {
		runCancel()
		if timeoutCancel != nil {
			timeoutCancel()
		}
	}
	// #nosec G204 -- command and args are explicit PTY session API inputs;
	// exec.Command does not invoke a shell.
	cmd := exec.Command(command, args...)
	cmd.Dir = workdir
	if len(env) > 0 {
		cmd.Env = append(os.Environ(), env...)
	}

	ptmx, err := pty.StartWithSize(cmd, &pty.Winsize{Rows: size.Rows, Cols: size.Cols})
	if err != nil {
		cancel()
		return nil, err
	}

	s := &Session{
		start:    cfg.Clock.Now(),
		clock:    cfg.Clock,
		size:     size,
		cancel:   cancel,
		output:   make(chan OutputChunk, 128),
		events:   make(chan Event, 256),
		waitDone: make(chan struct{}),
		readDone: make(chan struct{}),
	}
	s.impl = &unixImpl{cmd: cmd, file: ptmx}

	go s.readLoop(ptmx, cfg.BufferSize)
	go func() {
		select {
		case <-runCtx.Done():
			select {
			case <-s.waitDone:
				return
			default:
			}
			_ = s.Kill()
		case <-s.waitDone:
			return
		}
	}()
	go func() {
		<-s.waitDone
		<-s.readDone
		s.closeEvents()
	}()
	return s, nil
}

func (s *Session) readLoop(r io.Reader, bufferSize int) {
	defer close(s.readDone)
	defer close(s.output)
	buf := make([]byte, bufferSize)
	for {
		n, err := r.Read(buf)
		if n > 0 {
			s.emitOutput(buf[:n], nil, false)
		}
		if err != nil {
			if errors.Is(err, io.EOF) || errors.Is(err, syscall.EIO) {
				s.emitOutput(nil, nil, true)
			} else {
				s.emitOutput(nil, err, true)
			}
			return
		}
	}
}

type unixImpl struct {
	cmd  *exec.Cmd
	file *os.File
}

func (u *unixImpl) write(b []byte) (int, error) { return u.file.Write(b) }

func (u *unixImpl) resize(size Size) error {
	return pty.Setsize(u.file, &pty.Winsize{Rows: size.Rows, Cols: size.Cols})
}

func (u *unixImpl) close() error { return u.file.Close() }

func (u *unixImpl) kill() error {
	if u.cmd.Process == nil {
		return nil
	}
	pgid, err := syscall.Getpgid(u.cmd.Process.Pid)
	if err == nil {
		if killProcessGroup(pgid, syscall.SIGTERM) {
			time.Sleep(100 * time.Millisecond)
		}
		_ = killProcessGroup(pgid, syscall.SIGKILL)
		return nil
	}
	return u.cmd.Process.Kill()
}

func killProcessGroup(pgid int, sig syscall.Signal) bool {
	if pgid <= 0 {
		return false
	}
	err := syscall.Kill(-pgid, sig)
	return err == nil || errors.Is(err, syscall.ESRCH)
}

func (u *unixImpl) wait() ExitStatus {
	err := u.cmd.Wait()
	if err == nil {
		return ExitStatus{Code: 0, Exited: true}
	}
	status := ExitStatus{Code: -1, Err: err}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		if ws, ok := exitErr.Sys().(syscall.WaitStatus); ok {
			status.Code = ws.ExitStatus()
			status.Exited = ws.Exited()
			status.Signaled = ws.Signaled()
			if status.Signaled {
				status.Signal = ws.Signal().String()
			}
		} else {
			status.Code = exitErr.ExitCode()
		}
		return status
	}
	return status
}

func (s *Session) Size() Size {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.size
}

// SendBytes writes literal bytes to the PTY and records an input event.
func (s *Session) SendBytes(b []byte) error {
	if len(b) == 0 {
		return nil
	}
	if err := s.ensureOpen(); err != nil {
		return err
	}
	if _, err := s.impl.write(b); err != nil {
		return err
	}
	s.emit(Event{Kind: EventInput, Bytes: append([]byte(nil), b...)})
	return nil
}

// SendKey writes a named key sequence to the PTY and records an input event.
func (s *Session) SendKey(k Key) error {
	b, err := KeyBytes(k)
	if err != nil {
		return err
	}
	if err := s.ensureOpen(); err != nil {
		return err
	}
	if _, err := s.impl.write(b); err != nil {
		return err
	}
	s.emit(Event{Kind: EventInput, Bytes: b, Key: k})
	return nil
}

// Resize changes the PTY size and records a resize event.
func (s *Session) Resize(size Size) error {
	if err := validateSize(size); err != nil {
		return err
	}
	if err := s.ensureOpen(); err != nil {
		return err
	}
	if err := s.impl.resize(size); err != nil {
		return err
	}
	s.mu.Lock()
	s.size = size
	s.mu.Unlock()
	s.emit(Event{Kind: EventResize, Size: size})
	return nil
}

// Close cancels the session context and closes the PTY file descriptor.
func (s *Session) Close() error {
	s.mu.Lock()
	already := s.closed
	s.closed = true
	s.mu.Unlock()
	if already {
		return nil
	}
	if s.cancel != nil {
		s.cancel()
	}
	return s.impl.close()
}

// Kill terminates the process group where supported and records a signal event.
// If the process exits naturally at the same time, the signal event is best
// effort and may race with the exit event.
func (s *Session) Kill() error {
	s.mu.Lock()
	already := s.closed
	s.closed = true
	s.mu.Unlock()
	if already {
		return nil
	}
	if s.cancel != nil {
		s.cancel()
	}
	s.emit(Event{Kind: EventSignal, Signal: "kill"})
	return s.impl.kill()
}

// Wait blocks until the process exits and returns its exit status.
func (s *Session) Wait() ExitStatus {
	s.waitOnce.Do(func() {
		s.waitStat = s.impl.wait()
		s.mu.Lock()
		s.closed = true
		s.mu.Unlock()
		s.emit(Event{Kind: EventExit, Exit: &s.waitStat})
		close(s.waitDone)
		if s.cancel != nil {
			s.cancel()
		}
	})
	<-s.waitDone
	return s.waitStat
}

func (s *Session) ensureOpen() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return ErrClosed
	}
	return nil
}

func (s *Session) emit(ev Event) Event {
	s.mu.Lock()
	s.seq++
	ev.Seq = s.seq
	ev.At = s.clock.Now()
	ev.TMS = ev.At.Sub(s.start).Milliseconds()
	if ev.Kind == EventOutput {
		ev.Offset = s.offset
		s.offset += int64(len(ev.Bytes))
	}
	s.mu.Unlock()
	s.eventsMu.Lock()
	defer s.eventsMu.Unlock()
	if s.eventsClosed {
		return ev
	}
	select {
	case s.events <- ev:
	default:
	}
	return ev
}

func (s *Session) closeEvents() {
	s.eventsMu.Lock()
	defer s.eventsMu.Unlock()
	if s.eventsClosed {
		return
	}
	s.eventsClosed = true
	close(s.events)
}

func (s *Session) emitOutput(b []byte, readErr error, eof bool) {
	ev := Event{Kind: EventOutput, Bytes: append([]byte(nil), b...), Err: readErr}
	ev = s.emit(ev)
	chunk := OutputChunk{
		Seq:       ev.Seq,
		At:        ev.At,
		TMS:       ev.TMS,
		Offset:    ev.Offset,
		Bytes:     ev.Bytes,
		ReadError: readErr,
		EOF:       eof,
	}
	s.output <- chunk
}

func validateSize(size Size) error {
	if size.Rows == 0 || size.Cols == 0 {
		return fmt.Errorf("invalid terminal size rows=%d cols=%d", size.Rows, size.Cols)
	}
	return nil
}

