package claudetui

import (
	"context"
	"errors"
	"fmt"
	"io"
	"strings"
	"sync"

	"github.com/easel/fizeau/internal/pty/session"
)

type sessionPoolKey struct {
	harness string
	workdir string
}

type sessionStarter func(ctx context.Context, workdir string) (*session.Session, error)

type sessionPool struct {
	mu           sync.Mutex
	entries      map[sessionPoolKey]*sessionPoolEntry
	starter      sessionStarter
	readyMarkers []string
}

type sessionPoolEntry struct {
	mu      sync.Mutex
	session *session.Session
}

type sessionLease struct {
	Session *session.Session
	Reused  bool
	Output  string

	releaseOnce sync.Once
	release     func()
}

func (l *sessionLease) Close() {
	if l == nil {
		return
	}
	l.releaseOnce.Do(func() {
		if l.release != nil {
			l.release()
		}
	})
}

var claudeTUISessionPool = newSessionPool()

func newSessionPool() *sessionPool {
	return &sessionPool{
		entries:      make(map[sessionPoolKey]*sessionPoolEntry),
		starter:      defaultClaudeTUISessionStarter,
		readyMarkers: []string{"❯", "> "},
	}
}

func defaultClaudeTUISessionStarter(ctx context.Context, workdir string) (*session.Session, error) {
	return session.Start(ctx, "claude", nil, workdir, nil, session.Size{Rows: 50, Cols: 220})
}

func (p *sessionPool) Reset() {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.entries = make(map[sessionPoolKey]*sessionPoolEntry)
}

func (p *sessionPool) Acquire(ctx context.Context, workdir string) (*sessionLease, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	key := sessionPoolKey{harness: "claude-tui", workdir: workdir}
	entry := p.entryFor(key)
	entry.mu.Lock()

	if entry.session != nil {
		output, err := clearAndWaitForReady(ctx, entry.session, p.readyMarkers)
		if err == nil {
			lease := &sessionLease{
				Session: entry.session,
				Reused:  true,
				Output:  output,
				release: entry.mu.Unlock,
			}
			return lease, nil
		}
		_ = entry.session.Kill()
		_ = entry.session.Wait()
		entry.session = nil
	}

	starter := p.starter
	if starter == nil {
		starter = defaultClaudeTUISessionStarter
	}
	sess, err := starter(ctx, workdir)
	if err != nil {
		entry.mu.Unlock()
		return nil, err
	}
	output, err := waitForReady(ctx, sess, p.readyMarkers)
	if err != nil {
		_ = sess.Kill()
		_ = sess.Wait()
		entry.mu.Unlock()
		return nil, err
	}
	entry.session = sess
	lease := &sessionLease{
		Session: sess,
		Output:  output,
		release: entry.mu.Unlock,
	}
	return lease, nil
}

func (p *sessionPool) entryFor(key sessionPoolKey) *sessionPoolEntry {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.entries == nil {
		p.entries = make(map[sessionPoolKey]*sessionPoolEntry)
	}
	entry, ok := p.entries[key]
	if !ok {
		entry = &sessionPoolEntry{}
		p.entries[key] = entry
	}
	return entry
}

func clearAndWaitForReady(ctx context.Context, sess *session.Session, markers []string) (string, error) {
	if err := sess.SendBytes([]byte("/clear\r")); err != nil {
		return "", err
	}
	return waitForReady(ctx, sess, markers)
}

func waitForReady(ctx context.Context, sess *session.Session, markers []string) (string, error) {
	if sess == nil {
		return "", fmt.Errorf("nil session")
	}
	if len(markers) == 0 {
		return "", nil
	}
	var out strings.Builder
	for {
		if containsAny(out.String(), markers) {
			return out.String(), nil
		}
		select {
		case <-ctx.Done():
			return out.String(), ctx.Err()
		case chunk, ok := <-sess.Output():
			if !ok {
				if containsAny(out.String(), markers) {
					return out.String(), nil
				}
				return out.String(), errors.New("session closed before ready marker")
			}
			if chunk.ReadError != nil && !errors.Is(chunk.ReadError, io.EOF) {
				return out.String(), chunk.ReadError
			}
			if len(chunk.Bytes) == 0 {
				continue
			}
			out.Write(chunk.Bytes)
		}
	}
}

func containsAny(text string, markers []string) bool {
	for _, marker := range markers {
		if marker != "" && strings.Contains(text, marker) {
			return true
		}
	}
	return false
}

